dtsPropsFor.Logo:
/** Colour theme for the voxel palette. Default 'pink'. */
theme?: 'pink' | 'nature' | 'tt' | 'thingtime' | 'default';
/** Render the compact 3x3 icon mark instead of the full wordmark. */
icon?: boolean;
/** Pixel size of each voxel. Default 25. */
voxelSize?: number;
/** CSS unit appended to voxelSize. Default 'px'. */
unit?: string;
/** Custom voxel matrix (rows of colour-key digits) overriding the built-in logo art. */
matrix?: Array<string | Array<number | string>>;
/** Map of colour-key -> CSS colour, overriding the theme palette. */
colourMap?: Record<string | number, string>;
/** Opacity of the logo wrapper. */
opacity?: number;
/** Margin and padding applied to the wrapper (Chakra space token or value). */
space?: number | string;

dtsPropsFor.Icon:
/** Emoji name, alias, or raw emoji. Aliases include 'rainbow','heart','rocket','magic','star','user','search','lock','trash','money','wizard','crystal','book','image','video','mobile','world'. 'random' picks any emoji; an unknown name renders the shrug emoji. */
name?: string;
/** Font size of the emoji (Chakra fontSize value, e.g. '24px' | '2xl'). */
size?: string | number;
/** Extra Chakra style props merged onto the wrapping <Center>. */
chakras?: Record<string, unknown>;
/** Any Chakra <Center> style prop (color, bg, p, m, ...) passes through. */
[key: string]: any;

dtsPropsFor.Attention:
/** Width of the animated rainbow bar. Default '40px'. */
w?: string;
/** Any Chakra <Flex> style prop (color, bg, p, m, w, h, ...) passes through to the wrapper. */
[key: string]: any;

dtsPropsFor.RainbowSkeleton:
/** When true, renders `children` instead of the rainbow shimmer placeholder. */
loaded?: boolean;
children?: any;
/** Default size is 10x8px; override via Chakra width/height/borderRadius. Any Chakra <Flex> style prop passes through. */
[key: string]: any;
